#include <vector>
#include <queue>
#include <fstream>
#include <cstdio>
#include <climits>
#include <cmath>
#include <cstdint>
#include <stdexcept>
#include <chrono>
struct Case{int n,m;std::vector<int>R,C,F;};
std::vector<Case>load(const std::string&root){std::ifstream f(root+"/fixtures.bin",std::ios::binary);auto read=[&](){int v;if(!f.read((char*)&v,4))throw std::runtime_error("input bounds");return v;};int nc=read();std::vector<Case>cs;for(int k=0;k<nc;k++){Case c;c.n=read();c.m=read();for(int i=0;i<=c.n;i++)c.R.push_back(read());for(int i=0;i<2*c.m;i++)c.C.push_back(read());for(int i=0;i<2*c.m;i++)c.F.push_back(read());cs.push_back(c);}return cs;}
int main(int argc,char**argv){try{if(argc!=2)return 2;std::string root=argv[1];auto cs=load(root);std::ofstream out(root+"/oracle.bin",std::ios::binary);std::ofstream stats(root+"/oracle_stats.json");stats<<"{\"cases\":[";int ci=0;for(auto&c:cs){auto t=std::chrono::steady_clock::now();std::vector<long double>bc(c.n,0),errBC(c.n,0);std::vector<int>positive(c.n,0);const long double u=std::ldexp((long double)1,-24),factor=std::pow(1+u,4)/(1-u);uint64_t maxsigma=0;int maxdepth=0,maxdeg=0;for(int u=0;u<c.n;u++)maxdeg=std::max(maxdeg,c.R[u+1]-c.R[u]);for(int source=0;source<c.n;source++){std::vector<int>d(c.n,-1),q;q.reserve(c.n);std::vector<uint64_t>sigma(c.n,0);std::vector<long double>delta(c.n,0);d[source]=0;sigma[source]=1;q.push_back(source);for(size_t i=0;i<q.size();i++){int u=q[i];maxdepth=std::max(maxdepth,d[u]);for(int j=c.R[u];j<c.R[u+1];j++){int v=c.C[j];if(d[v]<0){d[v]=d[u]+1;q.push_back(v);}if(d[v]==d[u]+1){auto x=(unsigned __int128)sigma[v]+sigma[u];if(x>UINT64_MAX)throw std::runtime_error("shortest path UInt64 overflow");sigma[v]=x;maxsigma=std::max(maxsigma,sigma[v]);}}}for(int i=int(q.size())-1;i>=0;i--){int v=q[i];for(int j=c.R[v];j<c.R[v+1];j++){int u=c.C[j];if(d[u]==d[v]-1)delta[u]+=(long double)sigma[u]/sigma[v]*(1+delta[v]);}if(v!=source)bc[v]+=delta[v];}
// Independent positive-operation forward-error envelope, including arbitrary legal atomic sum order.
std::vector<long double>error(c.n,0);
for(int i=int(q.size())-1;i>=0;i--){int v=q[i];if(v==source)continue;long double trueSum=0,errSum=0;int terms=0;for(int j=c.R[v];j<c.R[v+1];j++){int w=c.C[j];if(d[w]==d[v]+1){long double ratio=(long double)sigma[v]/sigma[w],term=ratio*(1+delta[w]);trueSum+=term;errSum+=factor*ratio*(1+delta[w]+error[w])-term;terms++;}}long double g=terms*u/(1-terms*u);error[v]=errSum+g*(trueSum+errSum);errBC[v]+=error[v];if(delta[v]>0)positive[v]++;}
}
int n=c.n;out.write((char*)&n,4);long double pointwiseMaxRel=0;for(int v=0;v<c.n;v++){double value=double(bc[v]/2);long double g=positive[v]*u/(1-positive[v]*u);double budget=double((errBC[v]+g*(bc[v]+errBC[v]))/2);out.write((char*)&value,8);out.write((char*)&budget,8);if(value>0)pointwiseMaxRel=std::max(pointwiseMaxRel,(long double)budget/value);}long double unit=std::ldexp((long double)1,-24),K=(long double)maxdepth*(maxdeg+5)+c.n+2,gamma=K*unit/(1-K*unit);if(gamma>=.1)throw std::runtime_error("overlyweak FP32budget requires separate review");if(ci++)stats<<",";stats<<"{\"n\":"<<c.n<<",\"m\":"<<c.m<<",\"max_shortest_path_count\":"<<maxsigma<<",\"max_eccentricity\":"<<maxdepth<<",\"max_degree\":"<<maxdeg<<",\"positive_rounding_chain_K\":"<<double(K)<<",\"Float32_unit_roundoff\":5.9604644775390625e-8,\"componentwise_relative_budget\":";stats.precision(17);stats<<double(pointwiseMaxRel)<<",\"central_dual_reference_rtol\":"<<double(2*pointwiseMaxRel/(1-pointwiseMaxRel))<<",\"seconds\":"<<std::chrono::duration<double>(std::chrono::steady_clock::now()-t).count()<<"}";fprintf(stderr,"n%d complete maxsigma%llu diameter%d budget%.9g\n",c.n,(unsigned long long)maxsigma,maxdepth,double(pointwiseMaxRel));}stats<<"]}\n";return 0;}catch(const std::exception&e){fprintf(stderr,"%s\n",e.what());return 1;}}
